public TreeNode search(TreeNode node, int val) {
    if (node == null || node.val == val) return node;
    if (val < node.val) return search(node.left, val);
    return search(node.right, val);
}

public TreeNode delete(TreeNode node, int val) {
    if (node == null) return null;
    if (val < node.val) node.left = delete(node.left, val);
    else if (val > node.val) node.right = delete(node.right, val);
    else {
        if (node.left == null) return node.right;
        if (node.right == null) return node.left;
        TreeNode pred = findMax(node.left);
        node.val = pred.val;
        node.left = delete(node.left, pred.val);
    }
    return node;
}

public boolean isValidBST(TreeNode node, long min, long max) {
    if (node == null) return true;
    if (node.val <= min || node.val >= max) return false;
    return isValidBST(node.left, min, node.val) &&
           isValidBST(node.right, node.val, max);
}

public void inorder(TreeNode node, List<Integer> result) {
    if (node == null) return;
    inorder(node.left, result);
    result.add(node.val);
    inorder(node.right, result);
}

public TreeNode build(int[] inorder, int[] preorder, int inStart, int inEnd, int preStart, int preEnd) {
    if (inStart > inEnd) return null;
    int rootVal = preorder[preStart];
    TreeNode root = new TreeNode(rootVal);
    int rootIndex = findIndex(inorder, rootVal, inStart, inEnd);
    int leftSize = rootIndex - inStart;
    root.left = build(inorder, preorder, inStart, rootIndex - 1, preStart + 1, preStart + leftSize);
    root.right = build(inorder, preorder, rootIndex + 1, inEnd, preStart + leftSize + 1, preEnd);
    return root;
}

public boolean findPath(TreeNode node, int target, List<TreeNode> path) {
    if (node == null) return false;
    path.add(node);
    if (node.val == target) return true;
    if (findPath(node.left, target, path) || findPath(node.right, target, path)) return true;
    path.remove(path.size() - 1); // backtrack
    return false;
}

public int countRange(TreeNode node, int B, int C) {
    if (node == null) return 0;
    if (node.val < B) return countRange(node.right, B, C);
    if (node.val > C) return countRange(node.left, B, C);
    return 1 + countRange(node.left, B, C) + countRange(node.right, B, C);
}
